glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
attribute vec3 a_position;
attribute vec2 a_uv0;
attribute vec4 a_color;
varying vec2 v_uv;
varying vec4 v_color;
void main () {
    v_uv = a_uv0;
    v_color = a_color;
    gl_Position = cc_matViewProj * vec4(a_position, 1.0);
}

glsl3.frag:
precision highp float;
varying vec2 v_uv;
varying vec4 v_color;
uniform sampler2D texture;
uniform sampler2D colorTexture;
uniform MyUniform {
    vec2 colorTextureInfo;
    vec2 u_tileInfo;
    vec4 colorRGB1;
    vec4 colorRGB2;
    vec4 colorRGB3;
    vec4 colorRGB4;
    vec4 colorRGB5;
    vec4 colorRGB6;
    vec4 colorRGB7;
    vec4 colorRGB8;
};
void main () {
    vec2 uv = v_uv;
    vec4 texColor = texture2D(texture, uv);
    float index = floor(texColor.r * 255.0 + 0.5);
    index = index - 1.0;
    if (index == -1.0) {
      gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);
      return;
    }
    float scale = floor(texColor.g * 255.0);
    if (scale <= 0.0) {
      gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);
      return;
    }
    float scaleFactor = scale / 100.0;
    vec2 scaledUV = uv * u_tileInfo.xy;
    vec2 tileFrac = fract(scaledUV);
    float offset = (1.0 - scaleFactor) * 0.5;
    if (tileFrac.x < offset || tileFrac.x > (1.0 - offset) ||
        tileFrac.y < offset || tileFrac.y > (1.0 - offset)) {
        gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);
        return;
    }
    float isWhite = floor(texColor.b * 255.0 + 0.5);
    float needRGBColor = floor(texColor.a * 255.0 + 0.5);
    if (needRGBColor == 1.0) {
      if (index == 0.0) {
        gl_FragColor = colorRGB1;
      } else if (index == 1.0) {
        gl_FragColor = colorRGB2;
      } else if (index == 2.0) {
        gl_FragColor = colorRGB3;
      } else if (index == 3.0) {
        gl_FragColor = colorRGB4;
      } else if (index == 4.0) {
        gl_FragColor = colorRGB5;
      } else if (index == 5.0) {
        gl_FragColor = colorRGB6;
      } else if (index == 6.0) {
        gl_FragColor = colorRGB7;
      } else if (index == 7.0) {
        gl_FragColor = colorRGB8;
      }
    } else if (isWhite == 1.0) {
      gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
    } else {
      vec2 scaledTileFrac = (tileFrac - offset) / scaleFactor;
      float atlasX = mod(index, colorTextureInfo.x) / colorTextureInfo.x;
      float atlasY = floor(index / colorTextureInfo.x) / colorTextureInfo.y;
      float edgeOffset = 1.0 / 12.0;
      vec2 realTileFrac = edgeOffset + scaledTileFrac * (1.0 - 2.0 * edgeOffset);
      vec2 atlasUV = vec2(atlasX, atlasY) + realTileFrac * vec2(1.0/colorTextureInfo.x, 1.0/colorTextureInfo.y);
      gl_FragColor = texture2D(colorTexture, atlasUV) * v_color;
    }
}

